import app from 'flarum/common/app';
import { gradeOf, rankOf } from './curve';
const ROMAN = ['I', 'II', 'III', 'IV', 'V'];
const custom = (kind, step) => app.forum?.attribute('renown')?.[kind]?.[step - 1];

/** The admin's name for a rank (1–20), else the language pack's. */
export const rankName = rank => custom('ranks', rank)?.name || String(app.translator.trans(`ernestdefoe-renown.lib.ranks.${rank}`, {}, true));

/** A prestige tier, 1–20, or 21 for Eternal. */
export const tierName = tier => custom('tiers', tier)?.name || String(app.translator.trans(`ernestdefoe-renown.lib.tiers.${tier}`, {}, true));

/** "Veteran II" */
export const levelLabel = level => rankName(rankOf(level)) + ' ' + ROMAN[gradeOf(level) - 1];
export const rankIcon = rank => custom('ranks', rank)?.icon || null;
export const tierIcon = tier => custom('tiers', tier)?.icon || null;
flarum.reg.add('ernestdefoe-renown', 'common/names', { rankName: rankName,tierName: tierName,levelLabel: levelLabel,rankIcon: rankIcon,tierIcon: tierIcon, });